import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n + 1)]

    idx = 1
    for _ in range(n - 1):
        a = data[idx]
        b = data[idx + 1]
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    parent = [0] * (n + 1)
    order = [1]
    parent[1] = -1

    for v in order:
        for u in adj[v]:
            if u != parent[v]:
                parent[u] = v
                order.append(u)

    subtree = [1] * (n + 1)
    ans = n

    for v in reversed(order):
        if parent[v] > 0:
            subtree[parent[v]] += subtree[v]
            diff = abs(n - 2 * subtree[v])
            if diff < ans:
                ans = diff

    print(ans)

if __name__ == "__main__":
    main()
